package com.lmspilot.reporting.api;import com.lmspilot.contracts.Permissions;import com.lmspilot.reporting.domain.*;import com.lmspilot.support.api.ApiException;import com.lmspilot.support.security.*;import org.springframework.http.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;@Service public class ScheduledReportingService{private final ReportExportJobRepository jobs;private final ReportScheduleRepository schedules;private final LearnerCourseReadModelRepository models;private final EnrollmentScopeClient scope;private final ReportingProjectionService reporting;private final LicenseGuard license;public ScheduledReportingService(ReportExportJobRepository j,ReportScheduleRepository s,LearnerCourseReadModelRepository m,EnrollmentScopeClient e,ReportingProjectionService r,LicenseGuard l){jobs=j;schedules=s;models=m;scope=e;reporting=r;license=l;}@Transactional public ReportExportJobResponse createExport(CreateReportExportRequest i){license.requireFeature("REPORT_EXPORT",false);validateScope(i.scope());return response(jobs.save(new ReportExportJobEntity(CurrentUser.id(),i.scope())));}@Transactional(readOnly=true)public List<ReportExportJobResponse>myExports(){return jobs.findAllByOwnerIdOrderByCreatedAtDesc(CurrentUser.id()).stream().limit(100).map(this::response).toList();}@Transactional(readOnly=true)public ResponseEntity<byte[]>download(UUID id){var j=jobs.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"REPORT_EXPORT_NOT_FOUND","Không tìm thấy file báo cáo"));if(!j.getOwnerId().equals(CurrentUser.id()))throw new ApiException(HttpStatus.FORBIDDEN,"REPORT_EXPORT_SCOPE","Không có quyền tải báo cáo này");if(j.getStatus()!=ReportExportStatus.COMPLETED||j.getOutputCsv()==null)throw new ApiException(HttpStatus.CONFLICT,"REPORT_EXPORT_NOT_READY","Báo cáo chưa sẵn sàng");if(j.getExpiresAt().isBefore(Instant.now()))throw new ApiException(HttpStatus.GONE,"REPORT_EXPORT_EXPIRED","File báo cáo đã hết hạn");return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=learning-report-"+j.getId()+".csv").contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).body(j.getOutputCsv().getBytes(StandardCharsets.UTF_8));}@Transactional public ReportScheduleResponse createSchedule(ReportScheduleRequest i){license.requireFeature("REPORT_EXPORT",false);validateSchedule(i);validateScope(i.scope());return response(schedules.save(new ReportScheduleEntity(CurrentUser.id(),i.name().trim(),i.scope(),i.frequency(),i.dayOfWeek(),i.hourUtc(),i.enabled(),next(i.frequency(),i.dayOfWeek(),i.hourUtc(),Instant.now()))));}@Transactional public ReportScheduleResponse updateSchedule(UUID id,ReportScheduleRequest i){validateSchedule(i);validateScope(i.scope());var e=owned(id);e.setName(i.name().trim());e.setScope(i.scope());e.setFrequency(i.frequency());e.setDayOfWeek(i.dayOfWeek());e.setHourUtc(i.hourUtc());e.setEnabled(i.enabled());e.setUpdatedAt(Instant.now());e.setNextRunAt(next(i.frequency(),i.dayOfWeek(),i.hourUtc(),Instant.now()));return response(e);}@Transactional(readOnly=true)public List<ReportScheduleResponse>mySchedules(){return schedules.findAllByOwnerIdOrderByCreatedAtDesc(CurrentUser.id()).stream().map(this::response).toList();}@Transactional public void deleteSchedule(UUID id){schedules.delete(owned(id));}@Scheduled(fixedDelayString="${reporting.export-worker-delay-ms:5000}")@Transactional public void enqueueSchedules(){Instant n=Instant.now();for(var s:schedules.findTop50ByEnabledTrueAndNextRunAtBeforeOrderByNextRunAtAsc(n)){String key=s.getNextRunAt().truncatedTo(ChronoUnit.HOURS).toString();if(jobs.findByScheduleIdAndPeriodKey(s.getId(),key)==null)jobs.save(new ReportExportJobEntity(s.getOwnerId(),s.getScope(),s.getId(),key));s.setNextRunAt(next(s.getFrequency(),s.getDayOfWeek(),s.getHourUtc(),n.plusSeconds(60)));s.setUpdatedAt(n);}}@Scheduled(fixedDelayString="${reporting.export-worker-delay-ms:5000}")@Transactional public void processExports(){for(var j:jobs.findTop20ByStatusOrderByCreatedAtAsc(ReportExportStatus.PENDING)){j.setStatus(ReportExportStatus.PROCESSING);j.setStartedAt(Instant.now());try{var rows=rowsFor(j.getOwnerId(),j.getScope()).stream().map(x->new LearnerCourseRow(x.getEnrollmentId(),x.getClassId(),x.getCourseId(),x.getUserId(),x.getProgressPercent(),x.isCompleted(),x.getDueAt(),x.getLastScore(),x.getPassed(),x.getUpdatedAt())).toList();j.setOutputCsv(new String(reporting.exportCsv(rows),StandardCharsets.UTF_8));j.setRowCount(rows.size());j.setStatus(ReportExportStatus.COMPLETED);j.setCompletedAt(Instant.now());}catch(Exception e){j.setStatus(ReportExportStatus.FAILED);j.setErrorMessage(String.valueOf(e.getMessage()).substring(0,Math.min(1000,String.valueOf(e.getMessage()).length())));j.setCompletedAt(Instant.now());}}for(var j:jobs.findTop20ByStatusOrderByCreatedAtAsc(ReportExportStatus.COMPLETED))if(j.getExpiresAt().isBefore(Instant.now())){j.setStatus(ReportExportStatus.EXPIRED);j.setOutputCsv(null);}}private List<LearnerCourseReadModel>rowsFor(UUID owner,ReportScope s){return switch(s){case SELF->models.findAllByUserId(owner);case ASSIGNED->{Set<UUID>a=scope.assignedDeliveryIds(owner);yield models.findAll().stream().filter(x->a.contains(x.getClassId())).toList();}case SYSTEM->models.findAll();};}private void validateScope(ReportScope s){if(s==ReportScope.SYSTEM&&!CurrentUser.hasRole("ADMIN"))throw new ApiException(HttpStatus.FORBIDDEN,"REPORT_SCOPE_DENIED","Chỉ quản trị hệ thống được xuất báo cáo toàn hệ thống");if(s==ReportScope.ASSIGNED&&!CurrentUser.authorities().contains(Permissions.REPORTS_READ))throw new ApiException(HttpStatus.FORBIDDEN,"REPORT_SCOPE_DENIED","Không có quyền báo cáo theo phạm vi được giao");}private void validateSchedule(ReportScheduleRequest i){if(i.frequency()==ReportFrequency.WEEKLY&&i.dayOfWeek()==null)throw new ApiException(HttpStatus.BAD_REQUEST,"REPORT_DAY_REQUIRED","Lịch tuần cần chọn ngày trong tuần");}private ReportScheduleEntity owned(UUID id){var e=schedules.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"REPORT_SCHEDULE_NOT_FOUND","Không tìm thấy lịch báo cáo"));if(!e.getOwnerId().equals(CurrentUser.id()))throw new ApiException(HttpStatus.FORBIDDEN,"REPORT_SCHEDULE_SCOPE","Không có quyền sửa lịch này");return e;}private Instant next(ReportFrequency f,Integer day,int hour,Instant from){ZonedDateTime n=ZonedDateTime.ofInstant(from,ZoneOffset.UTC).withMinute(0).withSecond(0).withNano(0).withHour(hour);if(!n.toInstant().isAfter(from))n=n.plusDays(1);if(f==ReportFrequency.WEEKLY){DayOfWeek t=DayOfWeek.of(day==null?1:day);while(n.getDayOfWeek()!=t)n=n.plusDays(1);}return n.toInstant();}private ReportExportJobResponse response(ReportExportJobEntity e){return new ReportExportJobResponse(e.getId(),e.getScope(),e.getStatus(),e.getRowCount(),e.getErrorMessage(),e.getCreatedAt(),e.getCompletedAt(),e.getExpiresAt());}private ReportScheduleResponse response(ReportScheduleEntity e){return new ReportScheduleResponse(e.getId(),e.getName(),e.getScope(),e.getFrequency(),e.getDayOfWeek(),e.getHourUtc(),e.isEnabled(),e.getNextRunAt(),e.getUpdatedAt());}}
